using System.Text.Json;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.DataProtection;
using WebPush;
namespace HomeLibrary;
public sealed class WebSubscription {public string Endpoint{get;set;}="";public Dictionary<string,string> Keys{get;set;}=[];}
public sealed class PushRegistration {public string Owner{get;set;}="";public WebSubscription Subscription{get;set;}=new();public HashSet<string> Seen{get;set;}=[];public string LastStatus{get;set;}="Subscribed";public DateTimeOffset Created{get;set;}=DateTimeOffset.UtcNow;}
public sealed class PushState {public string PublicKey{get;set;}="";public string PrivateKey{get;set;}="";public List<PushRegistration> Subscriptions{get;set;}=[];}
public interface IPushTransport {Task Send(WebSubscription subscription,VapidDetails vapid,CancellationToken stop);}
public sealed class WebPushTransport:IPushTransport {
 public async Task Send(WebSubscription subscription,VapidDetails vapid,CancellationToken stop){using var http=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(15)};using var sender=new WebPushClient(http);await sender.SendNotificationAsync(new PushSubscription(subscription.Endpoint,subscription.Keys["p256dh"],subscription.Keys["auth"]),null,new Dictionary<string,object>{{"vapidDetails",vapid},{"TTL",3600}},stop);}
}
public sealed class PushNotifications {
 readonly object gate=new();readonly SemaphoreSlim sending=new(1,1);readonly string file,origin;readonly IDataProtector protector;readonly IPushTransport transport;readonly Store store;readonly BorrowerAccounts accounts;readonly BrowserAdmins browsers;readonly PurchaseSuggestions? suggestions;PushState state;
 public PushNotifications(string directory,string origin,IDataProtectionProvider provider,IPushTransport transport,Store store,BorrowerAccounts accounts,BrowserAdmins browsers,PurchaseSuggestions? suggestions=null){this.origin=origin.TrimEnd('/');this.transport=transport;this.store=store;this.accounts=accounts;this.browsers=browsers;this.suggestions=suggestions;file=Path.Combine(directory,"web-push.protected");protector=provider.CreateProtector("HomeLibrary.WebPush.v1");if(File.Exists(file))state=JsonSerializer.Deserialize<PushState>(protector.Unprotect(File.ReadAllBytes(file)),Library.Json)??throw new LibraryError("Notification settings could not be read.");else{var keys=VapidHelper.GenerateVapidKeys();state=new(){PublicKey=keys.PublicKey,PrivateKey=keys.PrivateKey};Save();}}
 IEnumerable<string> AdminEvents(LibraryState library)=>AdminNotifications.RequestEvents(library,accounts.List()).Concat(suggestions?.List().Where(x=>x.Status=="pending").Select(x=>"suggestion|"+x.Id)??Enumerable.Empty<string>());
 void Save(){File.WriteAllBytes(file+".tmp",protector.Protect(JsonSerializer.SerializeToUtf8Bytes(state,Library.Json)));if(!OperatingSystem.IsWindows())File.SetUnixFileMode(file+".tmp",UnixFileMode.UserRead|UnixFileMode.UserWrite);File.Move(file+".tmp",file,true);}
 static string Digest(string value)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)));
 public static void Validate(WebSubscription s){if(!Uri.TryCreate(s.Endpoint,UriKind.Absolute,out var u)||u.Scheme!="https"||u.Port!=443||u.UserInfo!=""||u.Fragment!=""||s.Endpoint.Length>2048)throw new LibraryError("Invalid push service endpoint.");var host=u.IdnHost;bool apple=host=="web.push.apple.com"||host.EndsWith(".push.apple.com",StringComparison.Ordinal);bool known=host=="fcm.googleapis.com"||host=="updates.push.services.mozilla.com"||host=="updates-autopush.webpush.mozgcp.net"||host.EndsWith(".notify.windows.com",StringComparison.Ordinal)||apple;if(!known)throw new LibraryError("This browser’s push service is not supported. Use Safari, Chrome, Firefox or Edge.");if(s.Keys==null||!s.Keys.TryGetValue("p256dh",out var key)||!s.Keys.TryGetValue("auth",out var auth)||Decode(key).Length!=65||Decode(auth).Length!=16)throw new LibraryError("Invalid notification subscription keys.");}
 static byte[] Decode(string input){try{if(input.Length>100)return [];return Convert.FromBase64String(input.Replace('-','+').Replace('_','/').PadRight((input.Length+3)/4*4,'='));}catch(FormatException){return [];}}
 public object Options(string owner){lock(gate)return new{configured=origin!="",publicKey=state.PublicKey,subscriptions=state.Subscriptions.Count(s=>s.Owner==owner)};}
 public object Status(){lock(gate)return new{configured=origin!="",borrowerDevices=state.Subscriptions.Count(s=>s.Owner.StartsWith("borrower:")),adminDevices=state.Subscriptions.Count(s=>s.Owner.StartsWith("admin:")),history=state.Subscriptions.Select(s=>new{role=s.Owner.StartsWith("admin:")?"Librarian":"Borrower",s.LastStatus,s.Created}).ToArray()};}
 public void Subscribe(string owner,WebSubscription sub){Validate(sub);lock(gate){if(origin=="")throw new LibraryError("Configure public HTTPS before enabling notifications.");var old=state.Subscriptions.Find(s=>s.Subscription.Endpoint==sub.Endpoint);if(old!=null&&old.Owner!=owner)throw new LibraryError("Turn notifications off for the previous account on this browser first.",409);if(old==null){if(state.Subscriptions.Count>=300||state.Subscriptions.Count(s=>s.Owner==owner)>=10)throw new LibraryError("Too many subscribed devices. Remove an unused subscription first.");old=new(){Owner=owner,Subscription=sub};if(owner.StartsWith("admin:"))foreach(var id in AdminEvents(store.Read().State))old.Seen.Add(Digest(id));state.Subscriptions.Add(old);}else old.Subscription=sub;Save();}}
 public void Remove(string owner,string endpoint){lock(gate){state.Subscriptions.RemoveAll(s=>s.Owner==owner&&s.Subscription.Endpoint==endpoint);Save();}}
 public void RemoveOwner(string owner){lock(gate){state.Subscriptions.RemoveAll(s=>s.Owner==owner);Save();}}
 bool Active(string owner)=>owner.StartsWith("admin:")?browsers.Active(owner[6..]):owner.StartsWith("borrower:")&&accounts.List().Any(a=>a.Id==owner[9..]&&a.Status=="active");
 public async Task Test(string owner,string endpoint,CancellationToken stop){WebSubscription sub;lock(gate){sub=state.Subscriptions.Find(s=>s.Owner==owner&&s.Subscription.Endpoint==endpoint)?.Subscription??throw new LibraryError("Enable notifications on this device first.");}if(!Active(owner))throw new LibraryError("This notification account is no longer active.",403);try{await transport.Send(sub,new VapidDetails(origin,state.PublicKey,state.PrivateKey),stop);}catch(Exception e)when(e is WebPushException or HttpRequestException or TaskCanceledException){throw new LibraryError("The push service did not confirm delivery. Check the device’s notification permission and try later.",503);}}
 public async Task Run(DateTimeOffset now,CancellationToken stop){if(!await sending.WaitAsync(0,stop))return;try{List<PushRegistration> subscriptions;lock(gate)subscriptions=state.Subscriptions.ToList();foreach(var sub in subscriptions){stop.ThrowIfCancellationRequested();if(!Active(sub.Owner)){RemoveOwner(sub.Owner);continue;}var library=store.Read().State;var events=new List<string>();if(sub.Owner.StartsWith("admin:"))events.AddRange(AdminEvents(library).Select(Digest));else{var account=accounts.List().Find(a=>a.Id==sub.Owner[9..]&&a.Status=="active");if(account==null)continue;var today=DateOnly.FromDateTime(now.LocalDateTime);foreach(var l in library.Loans.Where(l=>l.BorrowerId==account.BorrowerId&&l.ReturnedDate==null)){if(!DateOnly.TryParseExact(l.DueDate,"yyyy-MM-dd",out var due))continue;var days=due.DayNumber-today.DayNumber;var stage=days is >0 and <=2?"before":days==0?"due":days<=-7?"overdue":"";if(stage!="")events.Add(Digest(l.Id+"|"+l.DueDate+"|"+stage));}}
    lock(gate){if(!state.Subscriptions.Contains(sub)||events.All(sub.Seen.Contains))continue;foreach(var e in events)sub.Seen.Add(e);if(sub.Seen.Count>2000)sub.Seen=sub.Seen.TakeLast(1500).ToHashSet();sub.LastStatus="Delivery attempted";Save();}
    try{if(!Active(sub.Owner))continue;await transport.Send(sub.Subscription,new VapidDetails(origin,state.PublicKey,state.PrivateKey),stop);lock(gate){sub.LastStatus="Accepted by push service";Save();}}catch(WebPushException e){lock(gate){if((int)e.StatusCode is 404 or 410)state.Subscriptions.Remove(sub);else sub.LastStatus="Delivery unconfirmed; check permission or service";Save();}}catch(Exception e)when(e is HttpRequestException or TaskCanceledException){lock(gate){sub.LastStatus="Delivery unconfirmed; check permission or service";Save();}}
   }}finally{sending.Release();}}
}
public sealed class PushWorker(PushNotifications push,SnapshotGate snapshots,ILogger<PushWorker> logger):BackgroundService {protected override async Task ExecuteAsync(CancellationToken stop){using var timer=new PeriodicTimer(TimeSpan.FromMinutes(1));do{try{using var lease=await snapshots.Shared(stop);await push.Run(DateTimeOffset.Now,stop);}catch(OperationCanceledException)when(stop.IsCancellationRequested){return;}catch(Exception){logger.LogWarning("Notification check failed. Review notification settings.");}}while(await timer.WaitForNextTickAsync(stop));}}
